import { PUBLIC_API_URL } from "$env/static/public";
import { HTTP } from "$lib";
import { authenticatedMutation, type MutationIntent } from "$platform/authenticated-mutation";
import { readThreadContext } from "$platform/thread-read";

export const Get = (id: string) => {
	const http = new HTTP<Thread>(`${PUBLIC_API_URL}/thread/${id}`);
	return http.GET();
};

export const GetThreadVote = (threadId: string, signal?: AbortSignal) => readThreadContext<{ vote: number }>(`/thread/${encodeURIComponent(threadId)}/vote`, signal);

export const VoteThread = (threadId: string, vote: -1 | 1, intent?: MutationIntent) => authenticatedMutation<void>(`/thread/${encodeURIComponent(threadId)}/vote`, "POST", { vote }, intent);

export const UnvoteThread = (threadId: string, intent?: MutationIntent) => authenticatedMutation<void>(`/thread/${encodeURIComponent(threadId)}/vote`, "DELETE", undefined, intent);

export const Replies = (threadId: string, q: URLSearchParams) => { const query = [...q.entries()].map(([k, v]) => encodeURIComponent(k) + "=" + encodeURIComponent(v)).join("&"); return readThreadContext<ReplyFeedResponse>(`/thread/${encodeURIComponent(threadId)}/replies` + (query ? "?" + query : "")); };

export const GetReply = (threadId: string, replyId: string) => readThreadContext<Reply>(`/thread/${encodeURIComponent(threadId)}/replies/${encodeURIComponent(replyId)}`);

export interface CreateReplyRequest {
	parent_id?: number;
	body: string;
}

export const CreateReply = (threadId: string, payload: CreateReplyRequest, intent?: MutationIntent) => authenticatedMutation<Reply>(`/thread/${encodeURIComponent(threadId)}/replies`, "POST", payload, intent);

export const UpdateReply = (threadId: string, replyId: number, payload: { body: string; version: number }, intent?: MutationIntent) => authenticatedMutation<Reply>(`/thread/${encodeURIComponent(threadId)}/replies/${replyId}`, "PUT", payload, intent);

export const RemoveReply = (threadId: string, replyId: number, intent?: MutationIntent) => authenticatedMutation<void>(`/thread/${encodeURIComponent(threadId)}/replies/${replyId}`, "DELETE", undefined, intent);

export const DeleteReply = (threadId: string, replyId: number, intent?: MutationIntent) => authenticatedMutation<void>(`/thread/${encodeURIComponent(threadId)}/replies/${replyId}/hard`, "DELETE", undefined, intent);

export const VoteReply = (threadId: string, replyId: number, vote: -1 | 1, intent?: MutationIntent) => authenticatedMutation<void>(`/thread/${encodeURIComponent(threadId)}/replies/${replyId}/vote`, "POST", { vote }, intent);

export const UnvoteReply = (threadId: string, replyId: number, intent?: MutationIntent) => authenticatedMutation<void>(`/thread/${encodeURIComponent(threadId)}/replies/${replyId}/vote`, "DELETE", undefined, intent);
